-- Порядковый номер события: история заказа сортируется по нему, а не по
-- времени. Существующие события нумеруются в порядке их времени; номера
-- остаются в пределах 1..N, поэтому счетчик последовательности не сбивается.
ALTER TABLE "order_events" ADD COLUMN IF NOT EXISTS "seq" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY (sequence name "order_events_seq_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1);--> statement-breakpoint
UPDATE "order_events" SET "seq" = "ranked"."n" FROM (SELECT "id", row_number() OVER (ORDER BY "created_at", "seq") AS "n" FROM "order_events") AS "ranked" WHERE "order_events"."id" = "ranked"."id";
